import bpy
from bpy.app.translations import pgettext_iface as _
from bpy.app.translations import pgettext_tip as _tip
from bpy.props import BoolProperty, EnumProperty, IntProperty, StringProperty

from . import constants as const

# OSM map-size limits: preference attribute -> constants.py name. Order here
# is the draw order in the preferences window.
OSM_SIZE_LIMITS = {
    "osm_limit_forest": "FOREST_MAXSIZE",
    "osm_limit_water": "WATER_MAXSIZE",
    "osm_limit_small_rivers": "SMALL_RIVERS_MAXSIZE",
    "osm_limit_scree": "SCREE_MAXSIZE",
    "osm_limit_city": "CITY_MAXSIZE",
    "osm_limit_greenspace": "GREENSPACE_MAXSIZE",
    "osm_limit_farmland": "FARMLAND_MAXSIZE",
    "osm_limit_glacier": "GLACIER_MAXSIZE",
    "osm_limit_buildings": "BUILDINGS_MAXSIZE",
    "osm_limit_roads": "ROADS_MAXSIZE",
    "osm_limit_streets": "STREETS_PRIMARY_THRESHOLD",
    "osm_limit_coastline": "COASTLINE_MAXSIZE",
    "osm_limit_coastline_waterpoly": "COASTLINE_WATERPOLY_MAXSIZE",
}


def sync_osm_size_limits(prefs):
    """Push the preference values into constants.py's OSM size limits.
    Called from register() and from every limit property's update callback."""
    for attr, const_name in OSM_SIZE_LIMITS.items():
        const.set_osm_size_limit(const_name, getattr(prefs, attr))


def _on_osm_limit_update(self, context):
    sync_osm_size_limits(self)


def _osm_limit_prop(const_name, name, description):
    default = const.OSM_SIZE_LIMIT_DEFAULTS[const_name]
    return IntProperty(
        name=name,
        description=description + " (km)",
        default=default,
        min=1,
        soft_max=max(1000, default * 2),
        update=_on_osm_limit_update,
    )


# Default 3MF export profile. The profile *name* is what's persisted (in
# default_slicer_profile_id); the enum below is only a view onto it. A dynamic
# enum stores a bare index, so adding/removing a profile in the 3MF add-on
# would silently re-point a saved default at a different printer. "" =
# "Remember last used", which leaves the generator pages' own remembered
# profile (generator_settings.json) in charge; a named profile overrides it.
_DEFAULT_SLICER_UNSET = "__UNSET__"

# Blender only borrows the strings an items callback returns -- keep them
# alive (same reason as props._SLICER_PROFILE_ITEMS_CACHE).
_DEFAULT_SLICER_ITEMS_CACHE = {}


def _default_slicer_items(self, context):
    from .props import _slicer_profile_items_uncached

    items = [
        (
            _DEFAULT_SLICER_UNSET,
            "Remember last used",
            "Don't force a profile: new scenes start on the profile the generator pages last saved, or the built-in default if none",
        ),
        *_slicer_profile_items_uncached(),
    ]
    return _DEFAULT_SLICER_ITEMS_CACHE.setdefault(tuple(items), items)


def _get_default_slicer(self):
    ids = [item[0] for item in _default_slicer_items(self, None)]
    stored = self.default_slicer_profile_id
    # Unset, or a profile that's currently unavailable (3MF add-on disabled,
    # profile deleted): show "Remember last used" but leave the stored name alone so it
    # comes back if the profile does.
    return ids.index(stored) if stored in ids else 0


def _set_default_slicer(self, value):
    items = _default_slicer_items(self, None)
    self.default_slicer_profile_id = "" if value <= 0 else items[value][0]


class TP3D_AddonPreferences(bpy.types.AddonPreferences):
    bl_idname = __package__

    show_osm_size_limits: BoolProperty(
        name=_("Show OSM Map Size Limits"),
        default=False,
    )  # type: ignore

    osm_limit_forest: _osm_limit_prop(
        "FOREST_MAXSIZE", "Forest", "Forests are skipped above this map size"
    )  # type: ignore
    osm_limit_water: _osm_limit_prop(
        "WATER_MAXSIZE", "Water", "Water bodies and big rivers are skipped above this map size"
    )  # type: ignore
    osm_limit_small_rivers: _osm_limit_prop(
        "SMALL_RIVERS_MAXSIZE", "Small Rivers", "Small/minor waterways are skipped above this map size"
    )  # type: ignore
    osm_limit_scree: _osm_limit_prop(
        "SCREE_MAXSIZE", "Scree", "Scree is skipped above this map size"
    )  # type: ignore
    osm_limit_city: _osm_limit_prop(
        "CITY_MAXSIZE", "City", "City boundaries are skipped above this map size"
    )  # type: ignore
    osm_limit_greenspace: _osm_limit_prop(
        "GREENSPACE_MAXSIZE", "Greenspace", "Greenspaces are skipped above this map size"
    )  # type: ignore
    osm_limit_farmland: _osm_limit_prop(
        "FARMLAND_MAXSIZE", "Farmland", "Farmland is skipped above this map size"
    )  # type: ignore
    osm_limit_glacier: _osm_limit_prop(
        "GLACIER_MAXSIZE", "Glacier", "Glaciers are skipped above this map size"
    )  # type: ignore
    osm_limit_buildings: _osm_limit_prop(
        "BUILDINGS_MAXSIZE", "Buildings", "Buildings are skipped above this map size"
    )  # type: ignore
    osm_limit_roads: _osm_limit_prop(
        "ROADS_MAXSIZE", "Roads", "All roads are skipped above this map size"
    )  # type: ignore
    osm_limit_streets: _osm_limit_prop(
        "STREETS_PRIMARY_THRESHOLD",
        "Dense Streets",
        "Residential/service/footway/cycle/path roads are skipped above this map size",
    )  # type: ignore
    osm_limit_coastline: _osm_limit_prop(
        "COASTLINE_MAXSIZE",
        "Coastline (Overpass)",
        "Above this map size the ocean is built from the global water-polygon dataset instead of Overpass",
    )  # type: ignore
    osm_limit_coastline_waterpoly: _osm_limit_prop(
        "COASTLINE_WATERPOLY_MAXSIZE",
        "Coastline (Water Polygons)",
        "The ocean is skipped entirely above this map size",
    )  # type: ignore

    default_export_folder: StringProperty(
        name=_("Default Export Folder"),
        description=_tip("Default folder used when exporting STL / OBJ / 3MF files"),
        default="",
        subtype='DIR_PATH',
    )  # type: ignore

    default_slicer_profile_id: StringProperty(
        name=_("Default 3MF Export Profile"),
        default="",
        options={'HIDDEN'},
    )  # type: ignore

    default_slicer_profile: EnumProperty(
        name=_("Default 3MF Export Profile"),
        description=_tip(
            "Profile new scenes start with for 3MF export. Pick a profile to start every new scene on it, overriding the remembered one; the sidebar and generator pages can still change it per scene. \"Remember last used\" leaves it to the generator pages' saved profile"
        ),
        items=_default_slicer_items,
        get=_get_default_slicer,
        set=_set_default_slicer,
    )  # type: ignore

    openTopographyApiKey: StringProperty(
        name=_("OpenTopography API Key"),
        description=_tip("API key from portal.opentopography.org — free registration required for most datasets"),
        default="",
    )  # type: ignore

    dismissed_update_version: StringProperty(
        name=_("Dismissed Update Version"),
        description=_tip("Latest update version the user closed the notice for — re-shown once a newer version is found"),
        default="",
    )  # type: ignore

    def draw(self, context):
        from . import temp
        layout = self.layout

        # Premium status
        if temp.PREMIUMVERSION:
            box = layout.box()
            row = box.row()
            row.label(text=_("Premium Version"), icon='CHECKMARK')
            layout.separator()

        # OpenTopography API Key
        layout.label(text=_("OpenTopography API Key") + ":", icon='INTERNET')
        layout.prop(self, "openTopographyApiKey", text="")
        if not self.openTopographyApiKey:
            layout.label(text=_("Required for most datasets — free at portal.opentopography.org"), icon='ERROR')

        layout.separator()

        # Export
        layout.label(text=_("Export Settings:"), icon='EXPORT')
        layout.prop(self, "default_export_folder")
        if temp.has3mf:
            layout.prop(self, "default_slicer_profile")

        layout.separator()

        # OSM map-size limits
        row = layout.row()
        row.prop(
            self,
            "show_osm_size_limits",
            text=_("OSM Map Size Limits (km):"),
            icon='TRIA_DOWN' if self.show_osm_size_limits else 'TRIA_RIGHT',
            emboss=False,
        )
        if self.show_osm_size_limits:
            box = layout.box()
            box.label(text=_("OSM elements are skipped on maps larger than these sizes."), icon='INFO')
            box.label(text=_("Higher values mean larger Overpass downloads and slower generation."), icon='ERROR')
            grid = box.grid_flow(row_major=True, columns=2, even_columns=True, align=False)
            for attr in OSM_SIZE_LIMITS:
                grid.prop(self, attr)
            box.operator("tp3d.reset_osm_size_limits", icon='LOOP_BACK')

        layout.separator()

        # Updates
        from . import updater
        layout.label(text=_("Updates:"), icon='FILE_REFRESH')
        box = layout.box()
        current_str = ".".join(str(x) for x in const.ADDON_VERSION)

        if temp.PREMIUMVERSION:
            status = updater.premium_status
            latest_version = updater.premium_latest_version
            error_message = updater.premium_error_message
        else:
            status = updater.status
            latest_version = updater.latest_version
            error_message = updater.error_message

        if status == "idle":
            row = box.row(align=True)
            row.label(text=_("Current version: v{current_str}").format(current_str=current_str), icon='INFO')
            row.operator("tp3d.check_update", text=_("Check for Updates"), icon='FILE_REFRESH')

        elif status == "checking":
            box.label(text=_("Checking for updates..."), icon='TIME')

        elif status == "up_to_date":
            latest_str = ".".join(str(x) for x in latest_version)
            row = box.row(align=True)
            row.label(text=_("Up to date  (v{latest_str})").format(latest_str=latest_str), icon='CHECKMARK')
            row.operator("tp3d.check_update", text="", icon='FILE_REFRESH')

        elif status == "update_available":
            latest_str = ".".join(str(x) for x in latest_version)
            if self.dismissed_update_version != latest_str:
                row = box.row(align=True)
                row.label(text=_("Update available: v{latest_str}  (current: v{current_str})").format(latest_str=latest_str, current_str=current_str), icon='ERROR')
                row.operator("tp3d.check_update", text="", icon='FILE_REFRESH')
                row.operator("tp3d.dismiss_update", text="", icon='X').version = latest_str
                col = box.column()
                col.scale_y = 1.3
                if temp.PREMIUMVERSION:
                    col.operator("tp3d.open_premium_update", text=_("Get v{latest_str} on Patreon").format(latest_str=latest_str), icon='URL')
                else:
                    col.operator("tp3d.install_update", text=_("Download & Install v{latest_str}").format(latest_str=latest_str), icon='IMPORT')
                    box.label(text=_("Blender must be restarted after installing."), icon='INFO')
            else:
                row = box.row(align=True)
                row.label(text=_("Current version: v{current_str}").format(current_str=current_str), icon='INFO')
                row.operator("tp3d.check_update", text=_("Check for Updates"), icon='FILE_REFRESH')

        elif status == "error":
            row = box.row(align=True)
            msg = error_message[:60] + ("..." if len(error_message) > 60 else "")
            row.label(text=_("Check failed: {msg}").format(msg=msg), icon='CANCEL')
            row.operator("tp3d.check_update", text=_("Retry"), icon='FILE_REFRESH')

        layout.separator()


def get_prefs():
    """Convenience helper — returns the AddonPreferences instance."""
    return bpy.context.preferences.addons[__package__].preferences


def get_export_folder(tp3d):
    """The scene's export path, falling back to the Default Export Folder
    preference -- same fallback generation/export apply."""
    return tp3d.export_path or get_prefs().default_export_folder


def get_default_slicer_profile():
    """The 3MF export profile chosen in the preferences, or None when none is
    set or the chosen one isn't available right now (3MF add-on not loaded
    yet, profile deleted)."""
    try:
        name = get_prefs().default_slicer_profile_id
    except (KeyError, AttributeError):
        return None
    if not name:
        return None
    from .props import _slicer_profile_items_uncached

    if name not in {item[0] for item in _slicer_profile_items_uncached()}:
        return None
    return name
